pub fn classify_typed_item(item: Rc<Node>) -> TypedItemKind {
    {
        let item_has_structure: bool = (item.connective.clone() != Connective::NoConnective);
let is_bare_leaf: bool = (((((item_has_structure.clone() == false) && (item.body.clone() == None)) && ((item.params.clone().len() as i64) == 0)) && (item.transport.clone() == None)) && ((item.children.clone().len() as i64) == 0));
let kind: TypedItemKind = if (is_bare_leaf.clone() && is_type_alias_return_node(rt_type(item.clone()))) {
            TypedItemKind::TypedItemTypeAlias
} else {
            if (is_bare_leaf.clone() && !is_type_alias_return_node(rt_type(item.clone()))) {
                TypedItemKind::TypedItemTypeDecl
} else {
                if (item_has_structure.clone() && (item.transport.clone() == None)) {
                    TypedItemKind::TypedItemTypeDef
} else {
                    if ((item.body.clone() != None) && (item.type_annotation.clone() == None)) {
                        TypedItemKind::TypedItemFunction
} else {
                        if ((item.body.clone() != None) && (item.type_annotation.clone() != None)) {
                            TypedItemKind::TypedItemDataDef
} else {
                            if ((item.transport.clone() != None) && ((item.children.clone().len() as i64) > 0)) {
                                TypedItemKind::TypedItemServiceDef
} else {
                                if (((item.transport.clone() == None) && ((item.children.clone().len() as i64) > 0)) || ((((item.transport.clone() == None) && ((item.children.clone().len() as i64) == 0)) && ((item.properties.clone().len() as i64) > 0)) && (item.body.clone() == None))) {
                                    TypedItemKind::TypedItemResourceDef
} else {
                                    if (((((item.params.clone().len() as i64) > 0) && (item.body.clone() == None)) && (item.transport.clone() == None)) && ((item.children.clone().len() as i64) == 0)) {
                                        TypedItemKind::TypedItemTypeDecl
} else {
                                        TypedItemKind::TypedItemUnhandled
}
}
}
}
}
}
}
};
kind.clone()
}
}

#[derive(Debug, Clone, Copy, PartialEq, serde::Serialize, serde::Deserialize)]

pub enum ExprCategory {
    ExprCatLeaf,
    ExprCatCompound,
    ExprCatControlFlow,
    ExprCatBinding,
    ExprCatService,
    ExprCatNone,
}

pub fn classify_expr(texpr: Rc<Node>) -> ExprCategory {
    match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprLiteral { .. } => ExprCategory::ExprCatLeaf,
    ExprData::ExprError { .. } => ExprCategory::ExprCatLeaf,
    ExprData::ExprVar { .. } => ExprCategory::ExprCatLeaf,
    ExprData::ExprFieldAccess { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprCall { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprMethodCall { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprRecordLit { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprListLit => ExprCategory::ExprCatCompound,
    ExprData::ExprBinOp { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprUnaryOp { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprLambda { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprStringInterp => ExprCategory::ExprCatCompound,
    ExprData::ExprCast => ExprCategory::ExprCatCompound,
    ExprData::ExprIndex => ExprCategory::ExprCatCompound,
    ExprData::ExprSlice => ExprCategory::ExprCatCompound,
    ExprData::ExprMatch => ExprCategory::ExprCatControlFlow,
    ExprData::ExprIf => ExprCategory::ExprCatControlFlow,
    ExprData::ExprForEach => ExprCategory::ExprCatControlFlow,
    ExprData::ExprBlock => ExprCategory::ExprCatControlFlow,
    ExprData::ExprLet => ExprCategory::ExprCatBinding,
    ExprData::ExprReturn => ExprCategory::ExprCatControlFlow,
    ExprData::NoExprData => ExprCategory::ExprCatNone,
    _ => ExprCategory::ExprCatNone,
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]

pub enum FuncBodyShape {
    FuncBodyLet {
        name: String,
        value: Rc<Node>,
        rest: Option<Rc<Node>>,
    },
    FuncBodyBlock {
        stmts: Rc<Vec<Rc<Node>>>,
    },
    FuncBodyExpr {
        expr: Rc<Node>,
    },
}

pub fn classify_func_body(body: Rc<Node>, source_index: Option<Rc<NewlineIndex>>) -> Rc<FuncBodyShape> {
    match (*body.expr_data.clone()).clone() {
    ExprData::ExprLet => {
        let n: String = let_binding_name_at(body.clone(), source_index.clone());
let v: Rc<Node> = let_value(body.clone());
let rest: Option<Rc<Node>> = let_body(body.clone());
Rc::new(FuncBodyShape::FuncBodyLet {
    name: n.clone(),
    value: v.clone(),
    rest: rest.clone(),
})
},
    ExprData::ExprBlock => Rc::new(FuncBodyShape::FuncBodyBlock {
    stmts: body.children.clone(),
}),
    _ => Rc::new(FuncBodyShape::FuncBodyExpr {
    expr: body.clone(),
}),
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]

pub enum TcoExprShape {
    TcoCall {
        func: String,
        args: Rc<Vec<Rc<Node>>>,
    },
    TcoIf {
        condition: Rc<Node>,
        then_branch: Rc<Node>,
        else_branch: Option<Rc<Node>>,
    },
    TcoMatch {
        scrutinee: Rc<Node>,
        arms: Rc<Vec<Rc<Node>>>,
    },
    TcoLet {
        name: String,
        value: Rc<Node>,
        body: Option<Rc<Node>>,
    },
    TcoBlock {
        stmts: Rc<Vec<Rc<Node>>>,
    },
    TcoOther {
        expr: Rc<Node>,
    },
}

pub fn classify_tco_expr(texpr: Rc<Node>, source_index: Option<Rc<NewlineIndex>>) -> Rc<TcoExprShape> {
    match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprCall { .. } => Rc::new(TcoExprShape::TcoCall {
    func: expr_call_func_at(texpr.clone(), source_index.clone()),
    args: texpr.children.clone(),
}),
    ExprData::ExprIf => {
        let c: Rc<Node> = if_condition(texpr.clone());
let t: Rc<Node> = if_then_branch(texpr.clone());
let e: Option<Rc<Node>> = if_else_branch(texpr.clone());
Rc::new(TcoExprShape::TcoIf {
    condition: c.clone(),
    then_branch: t.clone(),
    else_branch: e.clone(),
})
},
    ExprData::ExprMatch => {
        let scrut: Rc<Node> = match_scrutinee(texpr.clone());
let arm_list: Rc<Vec<Rc<Node>>> = match_arm_nodes(texpr.clone());
Rc::new(TcoExprShape::TcoMatch {
    scrutinee: scrut.clone(),
    arms: arm_list.clone(),
})
},
    ExprData::ExprLet => {
        let n: String = let_binding_name_at(texpr.clone(), source_index.clone());
let v: Rc<Node> = let_value(texpr.clone());
let bd: Option<Rc<Node>> = let_body(texpr.clone());
Rc::new(TcoExprShape::TcoLet {
    name: n.clone(),
    value: v.clone(),
    body: bd.clone(),
})
},
    ExprData::ExprBlock => Rc::new(TcoExprShape::TcoBlock {
    stmts: texpr.children.clone(),
}),
    _ => Rc::new(TcoExprShape::TcoOther {
    expr: texpr.clone(),
}),
}
}

pub fn block_stmts_init(stmts: Rc<Vec<Rc<Node>>>) -> Rc<Vec<Rc<Node>>> {
    if ((stmts.clone().len() as i64) <= 1) {
        Rc::new(vec![])
} else {
        Rc::new(stmts.clone().iter().cloned().take(((stmts.clone().len() as i64) - 1) as usize).collect::<Vec<_>>())
}
}

pub fn is_tco_eligible(name: String, body: Rc<Node>, registry: Rc<HashMap<String, Rc<ItemInfo>>>) -> bool {
    match lookup_item(registry.clone(), name.clone()) {
    Some(info) => (info.is_self_recursive.clone() && (info.has_non_tail_self_call.clone() == false)),
    None => (expr_has_self_call(body.clone(), name.clone()) && (expr_has_non_tail_self_call(body.clone(), name.clone(), true) == false)),
}
}

pub fn is_self_recursive(name: String, body: Rc<Node>, registry: Rc<HashMap<String, Rc<ItemInfo>>>) -> bool {
    match lookup_item(registry.clone(), name.clone()) {
    Some(info) => info.is_self_recursive.clone(),
    None => expr_has_self_call(body.clone(), name.clone()),
}
}

pub fn tco_reassign_core(ordered_args: Rc<Vec<String>>, param_names: Rc<Vec<String>>, temp_var_prefix: String, temp_decl_prefix: String, temp_assign_op: String, stmt_terminator: String, continue_str: String, line_prefix: String) -> Rc<Vec<String>> {
    {
        let temp_lets: Rc<Vec<String>> = Rc::new({ let mut __result = Vec::new(); for pair in Rc::new(ordered_args.clone().iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { __result.push(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(line_prefix.clone(), temp_decl_prefix.clone()), temp_var_prefix.clone()), (pair.0.clone()).to_string()), temp_assign_op.clone()), pair.1.clone()), stmt_terminator.clone())); } __result });
let assigns: Rc<Vec<String>> = Rc::new({ let mut __result = Vec::new(); for pair in Rc::new(param_names.clone().iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { __result.push(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(line_prefix.clone(), pair.1.clone()), " = ".to_string()), temp_var_prefix.clone()), (pair.0.clone()).to_string()), stmt_terminator.clone())); } __result });
v2_rt::concat(v2_rt::concat(temp_lets.clone(), assigns.clone()), Rc::new(vec![v2_rt::concat(line_prefix.clone(), continue_str.clone())]))
}
}

pub fn emit_shared_tco_expr(frame: Rc<TcoFrame>, fn_name: String, emit_self_call_reassign: impl Fn(Rc<TcoReassignInput>) -> String, emit_non_self_call: impl Fn(Rc<TcoFrame>) -> String, emit_if: impl Fn(Rc<TcoFrame>) -> String, emit_match: impl Fn(Rc<TcoFrame>) -> String, emit_let: impl Fn(Rc<TcoFrame>) -> String, emit_block: impl Fn(Rc<TcoFrame>) -> String, emit_default_return: impl Fn(Rc<TcoFrame>) -> String) -> String {
    {
        let si: Option<Rc<NewlineIndex>> = frame.scope.clone().type_env.clone().source_index.clone();
match (*frame.expr.clone().expr_data.clone()).clone() {
    ExprData::ExprCall { .. } => if (expr_call_func_at(frame.expr.clone(), si.clone()).as_str() == fn_name.clone().as_str()) {
            emit_self_call_reassign(Rc::new(TcoReassignInput {
    args: frame.expr.clone().children.clone(),
    scope: frame.scope.clone(),
    depth: frame.depth.clone(),
}))
} else {
            emit_non_self_call(frame.clone())
},
    ExprData::ExprIf => emit_if(frame.clone()),
    ExprData::ExprMatch => emit_match(frame.clone()),
    ExprData::ExprLet => emit_let(frame.clone()),
    ExprData::ExprBlock => emit_block(frame.clone()),
    _ => emit_default_return(frame.clone()),
}
}
}

pub fn is_tco_candidate(texpr: Rc<Node>, func_name: String, source_index: Option<Rc<NewlineIndex>>) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprCall { .. } => (expr_call_func_at(texpr.clone(), source_index.clone()).as_str() == func_name.clone().as_str()),
    ExprData::ExprIf => {
            let then_cand: bool = is_tco_candidate(if_then_branch(texpr.clone()), func_name.clone(), source_index.clone());
let else_cand: bool = match if_else_branch(texpr.clone()) {
    Some(e) => is_tco_candidate(e.clone(), func_name.clone(), source_index.clone()),
    None => false,
};
(then_cand.clone() || else_cand.clone())
},
    ExprData::ExprMatch => { let mut __found = false; for arm_node in match_arm_nodes(texpr.clone()).iter().cloned() { if is_tco_candidate(arm_body(arm_node.clone()), func_name.clone(), source_index.clone()) { __found = true; break; } } __found },
    ExprData::ExprLet => match let_body(texpr.clone()) {
    Some(b) => is_tco_candidate(b.clone(), func_name.clone(), source_index.clone()),
    None => false,
},
    ExprData::ExprBlock => { let mut __found = false; for s in texpr.children.clone().iter().cloned() { if is_tco_candidate(s.clone(), func_name.clone(), source_index.clone()) { __found = true; break; } } __found },
    ExprData::NoExprData => { let mut __found = false; for child in texpr.children.clone().iter().cloned() { if is_tco_candidate(child.clone(), func_name.clone(), source_index.clone()) { __found = true; break; } } __found },
    _ => false,
}
    })
}

pub fn emit_ident(name: String, target: RenderTarget) -> String {
    match target.clone() {
    RenderTarget::Rust => {
        let snake: String = to_snake(name.clone());
if { let mut __found = false; for r in language_spec(RenderTarget::Rust).reserved_words.clone().keywords.clone().iter().cloned() { if (r.clone().as_str() == snake.clone().as_str()) { __found = true; break; } } __found } {
            v2_rt::concat(reserved_prefix(RenderTarget::Rust), snake.clone())
} else {
            snake.clone()
}
},
    RenderTarget::Go => {
        let parts: Rc<Vec<String>> = Rc::new(name.clone().split(&"_".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
if ((parts.clone().len() as i64) == 0) {
            name.clone()
} else {
            {
                let first_part: String = match parts.clone().first().cloned() {
    Some(p) => Rc::new({ let mut __result = Vec::new(); for c in Rc::new(p.clone().chars().map(|c| c as i64).collect::<Vec<_>>()).iter().cloned() { __result.push(to_lower_char(c.clone())); } __result }).join(&"".to_string()),
    None => "".to_string(),
};
let rest_parts: Rc<Vec<String>> = Rc::new({ let mut __result = Vec::new(); for pair in Rc::new({ let mut __result = Vec::new(); for pair in Rc::new(parts.clone().iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { if (pair.0.clone() > 0) { __result.push(pair); } } __result }).iter().cloned() { __result.push(capitalize_first(pair.1.clone())); } __result });
let camel: String = v2_rt::concat(first_part.clone(), rest_parts.clone().join(&"".to_string()));
if { let mut __found = false; for r in language_spec(RenderTarget::Go).reserved_words.clone().keywords.clone().iter().cloned() { if (r.clone().as_str() == camel.clone().as_str()) { __found = true; break; } } __found } {
                    v2_rt::concat(camel.clone(), reserved_suffix(RenderTarget::Go))
} else {
                    camel.clone()
}
}
}
},
    RenderTarget::Python => {
        let snake: String = to_snake(name.clone());
if { let mut __found = false; for r in language_spec(RenderTarget::Python).reserved_words.clone().keywords.clone().iter().cloned() { if (r.clone().as_str() == snake.clone().as_str()) { __found = true; break; } } __found } {
            v2_rt::concat(snake.clone(), reserved_suffix(RenderTarget::Python))
} else {
            snake.clone()
}
},
    RenderTarget::Dag => name.clone(),
}
}

pub fn emit_let_binding(name: String, value: String, target: RenderTarget) -> String {
    match target.clone() {
    RenderTarget::Rust => v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("let ".to_string(), emit_ident(name.clone(), RenderTarget::Rust)), " = ".to_string()), value.clone()), ";".to_string()),
    RenderTarget::Go => v2_rt::concat(v2_rt::concat(emit_ident(name.clone(), RenderTarget::Go), " := ".to_string()), value.clone()),
    RenderTarget::Python => v2_rt::concat(v2_rt::concat(emit_ident(name.clone(), RenderTarget::Python), " = ".to_string()), value.clone()),
    RenderTarget::Dag => v2_rt::concat(v2_rt::concat(v2_rt::concat("let ".to_string(), name.clone()), " = ".to_string()), value.clone()),
}
}

pub fn emit_return(value: String, target: RenderTarget) -> String {
    match target.clone() {
    RenderTarget::Rust => v2_rt::concat("return ".to_string(), value.clone()),
    RenderTarget::Go => v2_rt::concat("return ".to_string(), value.clone()),
    RenderTarget::Python => v2_rt::concat("return ".to_string(), value.clone()),
    RenderTarget::Dag => v2_rt::concat("return ".to_string(), value.clone()),
}
}

pub fn emit_unary_op(op: UnaryOpKind, operand_str: String, target: RenderTarget) -> String {
    match op.clone() {
    UnaryOpKind::Not => v2_rt::concat(emit_keyword("not".to_string(), target.clone()), operand_str.clone()),
    UnaryOpKind::Neg => v2_rt::concat("-".to_string(), operand_str.clone()),
}
}

pub fn emit_lambda(params_str: String, body_str: String, target: RenderTarget) -> String {
    match target.clone() {
    RenderTarget::Rust => v2_rt::concat(v2_rt::concat(v2_rt::concat("|".to_string(), params_str.clone()), "| ".to_string()), body_str.clone()),
    RenderTarget::Go => v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("func(".to_string(), params_str.clone()), ") interface{} { return ".to_string()), body_str.clone()), " }".to_string()),
    RenderTarget::Python => v2_rt::concat(v2_rt::concat(v2_rt::concat("lambda ".to_string(), params_str.clone()), ": ".to_string()), body_str.clone()),
    RenderTarget::Dag => v2_rt::concat(v2_rt::concat(v2_rt::concat("(".to_string(), params_str.clone()), ") => ".to_string()), body_str.clone()),
}
}

pub fn emit_error_expr(message: String, target: RenderTarget) -> String {
    {
        let msg: String = emit_string_literal(message.clone(), "".to_string());
match target.clone() {
    RenderTarget::Rust => v2_rt::concat(v2_rt::concat("compile_error!(".to_string(), msg.clone()), ")".to_string()),
    RenderTarget::Go => v2_rt::concat(v2_rt::concat("panic(".to_string(), msg.clone()), ")".to_string()),
    RenderTarget::Python => v2_rt::concat(v2_rt::concat("raise RuntimeError(".to_string(), msg.clone()), ")".to_string()),
    RenderTarget::Dag => v2_rt::concat(v2_rt::concat("error(".to_string(), msg.clone()), ")".to_string()),
}
}
}

pub fn emit_lambda_params(param_names: Rc<Vec<String>>, target: RenderTarget) -> String {
    {
        let param_strs: Rc<Vec<String>> = match target.clone() {
    RenderTarget::Go => Rc::new({ let mut __result = Vec::new(); for p in param_names.clone().iter().cloned() { __result.push(v2_rt::concat(emit_ident(p.clone(), RenderTarget::Go), " interface{}".to_string())); } __result }),
    _ => Rc::new({ let mut __result = Vec::new(); for p in param_names.clone().iter().cloned() { __result.push(emit_ident(p.clone(), target.clone())); } __result }),
};
param_strs.clone().join(&", ".to_string())
}
}

pub fn emit_list_lit_expr(element_strs: Rc<Vec<String>>, target: RenderTarget) -> String {
    if ((element_strs.clone().len() as i64) == 0) {
        match target.clone() {
    RenderTarget::Rust => "Rc::new(vec![])".to_string(),
    RenderTarget::Python => "[]".to_string(),
    RenderTarget::Go => "[]interface{}{}".to_string(),
    RenderTarget::Dag => "[]".to_string(),
}
} else {
        {
            let els_str: String = element_strs.clone().join(&", ".to_string());
match target.clone() {
    RenderTarget::Rust => v2_rt::concat(v2_rt::concat("Rc::new(vec![".to_string(), els_str.clone()), "])".to_string()),
    RenderTarget::Python => v2_rt::concat(v2_rt::concat("[".to_string(), els_str.clone()), "]".to_string()),
    RenderTarget::Go => v2_rt::concat(v2_rt::concat("[]interface{}{".to_string(), els_str.clone()), "}".to_string()),
    RenderTarget::Dag => v2_rt::concat(v2_rt::concat("[".to_string(), els_str.clone()), "]".to_string()),
}
}
}
}

pub fn emit_null_coalesce(l_str: String, r_str: String, target: RenderTarget) -> String {
    match target.clone() {
    RenderTarget::Rust => v2_rt::concat(v2_rt::concat(v2_rt::concat(l_str.clone(), ".unwrap_or_else(|| ".to_string()), r_str.clone()), ")".to_string()),
    RenderTarget::Python => v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("(".to_string(), l_str.clone()), " if ".to_string()), l_str.clone()), " is not None else ".to_string()), r_str.clone()), ")".to_string()),
    RenderTarget::Go => v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("func() interface{} { if ".to_string(), l_str.clone()), " != nil { return ".to_string()), l_str.clone()), " }; return ".to_string()), r_str.clone()), " }()".to_string()),
    RenderTarget::Dag => v2_rt::concat(v2_rt::concat(l_str.clone(), " ?? ".to_string()), r_str.clone()),
}
}

pub fn emit_shared_expr(texpr: Rc<Node>, target: RenderTarget, source_index: Option<Rc<NewlineIndex>>, wrap_result: impl Fn(String) -> String, recurse: impl Fn(Rc<Node>) -> String, emit_var: impl Fn(Rc<Node>) -> String, emit_field_access: impl Fn(Rc<Node>) -> String, emit_call: impl Fn(Rc<Node>) -> String, emit_method_call: impl Fn(Rc<Node>) -> String, emit_match: impl Fn(Rc<Node>) -> String, emit_if: impl Fn(Rc<Node>) -> String, emit_let: impl Fn(Rc<Node>) -> String, emit_record_lit: impl Fn(Rc<Node>) -> String, emit_string_interp: impl Fn(Rc<Node>) -> String, emit_block: impl Fn(Rc<Node>) -> String, emit_cast: impl Fn(Rc<Node>) -> String, emit_for_each: impl Fn(Rc<Node>) -> String, emit_index: impl Fn(Rc<Node>) -> String, emit_slice: impl Fn(Rc<Node>) -> String, emit_bin_op: impl Fn(Rc<Node>) -> String) -> String {
    match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprLiteral { value: v, .. } => wrap_result(emit_literal(v.clone(), target.clone())),
    ExprData::ExprError { message: message, .. } => wrap_result(emit_error_expr(message.clone(), target.clone())),
    ExprData::ExprVar { .. } => emit_var(texpr.clone()),
    ExprData::ExprFieldAccess { .. } => emit_field_access(texpr.clone()),
    ExprData::ExprCall { .. } => emit_call(texpr.clone()),
    ExprData::ExprMethodCall { .. } => emit_method_call(texpr.clone()),
    ExprData::ExprMatch => emit_match(texpr.clone()),
    ExprData::ExprIf => emit_if(texpr.clone()),
    ExprData::ExprLet => emit_let(texpr.clone()),
    ExprData::ExprRecordLit { .. } => emit_record_lit(texpr.clone()),
    ExprData::ExprBinOp { .. } => emit_bin_op(texpr.clone()),
    ExprData::ExprUnaryOp { op: op, .. } => {
        let operand: Rc<Node> = unaryop_operand(texpr.clone());
wrap_result(emit_unary_op(op.clone(), recurse(operand.clone()), target.clone()))
},
    ExprData::ExprLambda { .. } => {
        let body: Rc<Node> = lambda_body(texpr.clone());
wrap_result(emit_lambda(emit_lambda_params(lambda_param_names_at(texpr.clone(), source_index.clone()), target.clone()), recurse(body.clone()), target.clone()))
},
    ExprData::ExprStringInterp => emit_string_interp(texpr.clone()),
    ExprData::ExprBlock => emit_block(texpr.clone()),
    ExprData::ExprCast => emit_cast(texpr.clone()),
    ExprData::ExprForEach => emit_for_each(texpr.clone()),
    ExprData::ExprIndex => emit_index(texpr.clone()),
    ExprData::ExprSlice => emit_slice(texpr.clone()),
    ExprData::ExprListLit => wrap_result(emit_list_lit_expr(Rc::new({ let mut __result = Vec::new(); for el in texpr.children.clone().iter().cloned() { __result.push(recurse(el.clone())); } __result }), target.clone())),
    ExprData::ExprReturn => {
        let ret_val: Rc<Node> = return_value(texpr.clone());
wrap_result(emit_return(recurse(ret_val.clone()), target.clone()))
},
    ExprData::NoExprData => wrap_result("".to_string()),
}
}

pub fn emit_default_bin_op(texpr: Rc<Node>, target: RenderTarget, recurse: impl Fn(Rc<Node>) -> String, wrap_result: impl Fn(String) -> String) -> String {
    match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprBinOp { op: op, .. } => {
        let left: Rc<Node> = binop_left(texpr.clone());
let right: Rc<Node> = binop_right(texpr.clone());
let left_str: String = recurse(left.clone());
let right_str: String = recurse(right.clone());
if is_null_coalesce(op.clone()) {
            wrap_result(emit_null_coalesce(left_str.clone(), right_str.clone(), target.clone()))
} else {
            {
                let op_str: String = emit_bin_op_symbol(op.clone(), target.clone());
wrap_result(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("(".to_string(), left_str.clone()), " ".to_string()), op_str.clone()), " ".to_string()), right_str.clone()), ")".to_string()))
}
}
},
    _ => wrap_result(emit_error_expr("emit_default_bin_op expected ExprBinOp".to_string(), target.clone())),
}
}
